CREATE TABLE events (
    id          INTEGER PRIMARY KEY,
    regatta_id  INTEGER NOT NULL REFERENCES regattas(id),
    season_year INTEGER NOT NULL,
    start_date  TEXT,
    end_date    TEXT,
    source_url  TEXT,
    notes       TEXT,
    UNIQUE(regatta_id, season_year)
);
