CREATE TABLE scrape_runs (
    id              INTEGER PRIMARY KEY,
    source_name     TEXT NOT NULL,      -- 'jog' | 'rorc' | ...
    started_at      TEXT NOT NULL DEFAULT (datetime('now')),
    finished_at     TEXT,
    status          TEXT,               -- 'success' | 'partial' | 'failed'
    records_upserted INTEGER,
    notes           TEXT
);
CREATE INDEX idx_race_entries_boat ON race_entries(boat_id);
CREATE INDEX idx_race_entries_race ON race_entries(race_id);
CREATE INDEX idx_race_entries_sailmaker ON race_entries(sailmaker_id);
CREATE INDEX idx_races_event ON races(event_id);
CREATE INDEX idx_events_regatta_year ON events(regatta_id, season_year);
CREATE INDEX idx_boat_sailmaker_history_boat ON boat_sailmaker_history(boat_id);
